changeSet.sql:
     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'list_my_cafes', 'Kafelarim',
             'List the cafes owned by the current user (slug, names in each language, contacts, active flag). Call this first to find the cafeSlug other tools need.',
             'GET', '/api/v1/cafes/my',
             $json${"type": "object", "properties": {}}$json$::jsonb,
             false, '["CAFE_ADMIN"]'::jsonb, true);

     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'search_cafes', 'Kafelarni qidirish',
             'Search all cafes on the platform (paged). Matches slug, phone or address. Use it to find a cafeSlug.',
             'GET', '/api/v1/cafes',
             $json${"type": "object", "properties": {
  "search": {"type": "string", "description": "Part of the cafe slug, phone or address"},
             "page": {"type": "integer", "minimum": 0, "description": "Page number, 0-based"},
             "size": {"type": "integer", "minimum": 1, "maximum": 100, "description": "Page size"}
}}$json$::jsonb,
             false, '["SUPER_ADMIN"]'::jsonb, true);

     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'list_categories', 'Kategoriyalar',
             'List the menu categories of a cafe in display order (slug, names, active, product count).',
             'GET', '/api/v1/cafes/{cafeSlug}/categories',
             $json${"type": "object", "properties": {
  "cafeSlug": {"type": "string", "description": "Cafe slug"}
}, "required": ["cafeSlug"]}$json$::jsonb,
             false, '["CAFE_ADMIN", "SUPER_ADMIN"]'::jsonb, true);

     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'list_products', 'Taomlar',
             'List the dishes of a cafe, optionally only one category: slug, category, names, price, running discount price, portion, badges, shown on menu (active), in stock (available).',
             'GET', '/api/v1/cafes/{cafeSlug}/products',
             $json${"type": "object", "properties": {
  "cafeSlug": {"type": "string", "description": "Cafe slug"},
             "categorySlug": {"type": "string", "description": "Optional category slug to filter by"}
}, "required": ["cafeSlug"]}$json$::jsonb,
             false, '["CAFE_ADMIN", "SUPER_ADMIN"]'::jsonb, true);

     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'create_category', 'Kategoriya qo''shish',
             'Add a menu category to a cafe. The user confirms in a form.',
             'POST', '/api/v1/cafes/{cafeSlug}/categories',
             $json${"type": "object", "properties": {
  "cafeSlug": {"type": "string", "title": "Kafe", "description": "Cafe slug",
             "x-options": {"path": "/api/v1/cafes/my", "items": "data.cafes", "value": "slug",
             "label": "nameTranslations.uz"}},
             "nameTranslations": {"type": "object", "title": "Nomi",
             "description": "Category name per language code",
             "properties": {
      "uz": {"type": "string", "title": "O'zbekcha"},
             "ru": {"type": "string", "title": "Ruscha"},
             "en": {"type": "string", "title": "Inglizcha"}
    }, "required": ["uz"]},
             "active": {"type": "boolean", "title": "Menyuda ko'rsatish", "default": true}
}, "required": ["cafeSlug", "nameTranslations"]}$json$::jsonb,
             true, '["CAFE_ADMIN", "SUPER_ADMIN"]'::jsonb, true);

     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'create_product', 'Taom qo''shish',
             'Add a dish or drink to a cafe menu. Fill in what the user said (name, price, portion, category...) and leave the rest out; the user completes and confirms it in a form. Translate the name into ru and en yourself when you can.',
             'POST', '/api/v1/cafes/{cafeSlug}/products',
             $json${"type": "object", "properties": {
  "cafeSlug": {"type": "string", "title": "Kafe", "description": "Cafe slug",
             "x-options": {"path": "/api/v1/cafes/my", "items": "data.cafes", "value": "slug",
             "label": "nameTranslations.uz"}},
             "categorySlug": {"type": "string", "title": "Kategoriya",
             "description": "Category slug in that cafe",
             "x-options": {"path": "/api/v1/cafes/{cafeSlug}/categories", "value": "slug",
             "label": "nameTranslations.uz"}},
             "nameTranslations": {"type": "object", "title": "Nomi",
             "description": "Dish name per language code",
             "properties": {
      "uz": {"type": "string", "title": "O'zbekcha"},
             "ru": {"type": "string", "title": "Ruscha"},
             "en": {"type": "string", "title": "Inglizcha"}
    }, "required": ["uz"]},
             "price": {"type": "number", "title": "Narxi (so'm)", "minimum": 0},
             "portion": {"type": "string", "title": "Porsiya",
             "description": "Free text such as 0.5 l, 330 ml or 300 g", "maxLength": 50},
             "descriptionTranslations": {"type": "object", "title": "Tavsif",
             "description": "Short description per language code",
             "properties": {
      "uz": {"type": "string", "title": "O'zbekcha", "x-multiline": true},
             "ru": {"type": "string", "title": "Ruscha", "x-multiline": true},
             "en": {"type": "string", "title": "Inglizcha", "x-multiline": true}
    }},
             "tags": {"type": "array", "title": "Belgilar", "description": "Menu badges",
             "items": {"type": "string", "enum": ["NEW", "HIT", "SPICY"]},
             "x-enum-labels": {"NEW": "Yangi", "HIT": "Hit", "SPICY": "Achchiq"}},
             "available": {"type": "boolean", "title": "Mavjud", "default": true},
             "active": {"type": "boolean", "title": "Menyuda ko'rsatish", "default": true}
}, "required": ["cafeSlug", "categorySlug", "nameTranslations", "price"]}$json$::jsonb,
             true, '["CAFE_ADMIN", "SUPER_ADMIN"]'::jsonb, true);

     INSERT INTO ai_tool (id, name, title, description, http_method, path_template, input_schema,
                          requires_confirmation, allowed_roles, active)
     VALUES (gen_random_uuid(), 'set_product_availability', 'Mavjudlikni o''zgartirish',
             'Mark a dish as sold out (available=false) or back in stock (available=true). Find the product slug with list_products first. The user confirms in a form.',
             'PATCH', '/api/v1/cafes/{cafeSlug}/products/{slug}/availability',
             $json${"type": "object", "properties": {
  "cafeSlug": {"type": "string", "title": "Kafe", "description": "Cafe slug",
             "x-options": {"path": "/api/v1/cafes/my", "items": "data.cafes", "value": "slug",
             "label": "nameTranslations.uz"}},
             "slug": {"type": "string", "title": "Taom", "description": "Product slug",
             "x-options": {"path": "/api/v1/cafes/{cafeSlug}/products", "value": "slug",
             "label": "nameTranslations.uz"}},
             "available": {"type": "boolean", "title": "Mavjud", "description": "false = sold out"}
}, "required": ["cafeSlug", "slug", "available"]}$json$::jsonb,
             true, '["CAFE_ADMIN", "SUPER_ADMIN"]'::jsonb, true);
